function setText(element, value) { if (value !== undefined) element.innerHTML = value; }
let activeFilter = 'all';
function renderProjects(language) {
  const grid = document.querySelector('#project-grid');
  const visible = projects.filter((project) => activeFilter === 'all' || project.category === activeFilter);
  grid.innerHTML = visible.map((project) => `<article class="project-card reveal ${project.featured ? 'project-featured' : ''}"><div><span class="project-index">PROJECT / ${project.index}</span><h3>${project.title[language]}</h3><p>${project.description[language]}</p></div><div><details class="project-detail"><summary>${translations[language].projects.detail}<span aria-hidden="true"> +</span></summary><p>${project.detail[language]}</p></details><div class="project-bottom"><div class="project-tech">${project.tech.map((item) => `<span>${item}</span>`).join('')}</div>${project.source ? `<a class="source-link" href="${project.source}" target="_blank" rel="noopener noreferrer">${project.example ? translations[language].projects.example : translations[language].projects.source} ↗</a>` : ''}</div></div></article>`).join('');
  requestAnimationFrame(() => grid.querySelectorAll('.reveal').forEach((element) => observer.observe(element)));
}
function renderWorkflow(language, index) {
  const workflow = translations[language].workflow;
  const panel = document.querySelector('#workflow-panel');
  panel.innerHTML = `<span class="workflow-number">0${index + 1} / 03</span><h2>${workflow.steps[index].title}</h2><p>${workflow.steps[index].text}</p>`;
  document.querySelectorAll('[data-step]').forEach((button, buttonIndex) => { button.textContent = workflow.tabs[buttonIndex]; button.setAttribute('aria-selected', String(buttonIndex === index)); button.tabIndex = buttonIndex === index ? 0 : -1; });
  panel.setAttribute('aria-labelledby', `workflow-tab-${index}`);
  document.querySelector('.workflow-track i').style.width = `${(index + 1) * 33.333}%`;
}
function applyLanguage(language) {
  const dictionary = translations[language];
  document.documentElement.lang = language;
  document.title = language === 'de' ? 'Om Vaghasiya — AI Engineer' : 'Om Vaghasiya — AI Engineer';
  document.querySelectorAll('[data-i18n]').forEach((element) => setText(element, dictionaryLookup(dictionary, element.dataset.i18n)));
  document.querySelectorAll('.lang-button').forEach((button) => { const active = button.dataset.lang === language; button.classList.toggle('active', active); button.setAttribute('aria-pressed', String(active)); });
  renderProjects(language);
  document.querySelectorAll('.filter-button').forEach((button, index) => { button.textContent = dictionary.projects.filters[index]; });
  renderWorkflow(language, Number(document.querySelector('[data-step][aria-selected="true"]')?.dataset.step || 0));
  localStorage.setItem('portfolio-language', language);
}
function dictionaryLookup(object, path) { return path.split('.').reduce((value, key) => value && value[key], object); }
const observer = new IntersectionObserver((entries) => entries.forEach((entry) => { if (entry.isIntersecting) { entry.target.classList.add('is-visible'); observer.unobserve(entry.target); } }), { threshold: 0.12 });
document.querySelectorAll('.reveal').forEach((element) => observer.observe(element));
document.querySelectorAll('.lang-button').forEach((button) => button.addEventListener('click', () => applyLanguage(button.dataset.lang)));
document.querySelectorAll('.filter-button').forEach((button) => button.addEventListener('click', () => { activeFilter = button.dataset.filter; document.querySelectorAll('.filter-button').forEach((item) => { const selected = item === button; item.classList.toggle('active', selected); item.setAttribute('aria-pressed', String(selected)); }); renderProjects(document.documentElement.lang); }));
document.querySelectorAll('[data-step]').forEach((button) => { button.addEventListener('click', () => renderWorkflow(document.documentElement.lang, Number(button.dataset.step))); button.addEventListener('keydown', (event) => { if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return; event.preventDefault(); const current = Number(button.dataset.step); const next = (current + (event.key === 'ArrowRight' ? 1 : 2)) % 3; const target = document.querySelector(`[data-step="${next}"]`); target.focus(); renderWorkflow(document.documentElement.lang, next); }); });
const menuToggle = document.querySelector('.menu-toggle');
const siteNav = document.querySelector('.site-nav');
menuToggle.addEventListener('click', () => { const open = siteNav.classList.toggle('is-open'); menuToggle.setAttribute('aria-expanded', String(open)); });
siteNav.querySelectorAll('a').forEach((link) => link.addEventListener('click', () => { siteNav.classList.remove('is-open'); menuToggle.setAttribute('aria-expanded', 'false'); }));
applyLanguage(localStorage.getItem('portfolio-language') || 'en');
